import{CommissionerCard}from"./CommissionerCard.js";export function Timeline(i){if(0===i.length)return'<div class="no-results">No Commissioners found matching your criteria.</div>';return`\n        <div class="timeline-container">\n            <div class="timeline-nav-wrapper">\n                <div class="timeline-track"></div>\n                <div class="timeline-nav">\n                    ${i.map(i=>`\n        <div class="timeline-nav-item" data-target="cec-${i.originalIndex}" title="${i.name} (${i.appointmentDate.split(" ").pop()})">\n            <div class="timeline-dot"></div>\n            <div class="timeline-year-label">${i.appointmentDate.split(" ").pop()}</div>\n        </div>\n    `).join("")}\n                </div>\n            </div>\n            <div class="cards-grid">\n                ${i.map(i=>`\n        <div class="card-wrapper">\n            ${CommissionerCard(i,i.originalIndex)}\n        </div>\n    `).join("")}\n            </div>\n        </div>\n    `}